import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import './App.css';
import Login from './pages/Login';
import AdminDashboard from './pages/AdminDashboard';
import ManagerDashboard from './pages/ManagerDashboard';
import EmployeeDashboard from './pages/EmployeeDashboard';
import FaceDetection from './pages/FaceDetection';
import AttendanceManagement from './pages/AttendanceManagement';
import SalaryTracker from './pages/SalaryTracker';
import EmployeeRecords from './pages/EmployeeRecords';
import UserManagement from './pages/UserManagement';
import ProfileSetting from './pages/ProfileSetting';
import AttendanceScanner from './pages/AttendanceScanner';
import QRCodeGenerator from './pages/QRCodeGenerator';
import ProtectedRoute from './components/ProtectedRoute';
import { verifySession } from './utils/authService';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if user is already logged in using JWT token
    const authData = verifySession();
    
    if (authData) {
      setUser(authData);
    }
    setLoading(false);
  }, []);

  const handleLogout = () => {
    // Clear all auth data
    sessionStorage.removeItem('authToken');
    sessionStorage.removeItem('sessionId');
    sessionStorage.removeItem('authData');
    localStorage.removeItem('authToken');
    localStorage.removeItem('authData');
    
    // Legacy cleanup
    localStorage.removeItem('employeeId');
    localStorage.removeItem('employeeName');
    localStorage.removeItem('userRole');
    localStorage.removeItem('isAdmin');
    localStorage.removeItem('isManager');
    
    setUser(null);
  };

  if (loading) {
    return (
      <div style={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '100vh',
        background: 'linear-gradient(135deg, #0a192f 0%, #1a3a5c 100%)',
        color: 'white',
        fontSize: '1.2rem',
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
      }}>
        Loading...
      </div>
    );
  }

  return (
    <Router>
      <Routes>
        <Route path="/login" element={<Login setUser={setUser} />} />
        <Route path="/qr-generator" element={<QRCodeGenerator />} />
        
        <Route 
          path="/admin" 
          element={
            <ProtectedRoute user={user} requiredRole="admin">
              <AdminDashboard user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />
        
        <Route 
          path="/manager" 
          element={
            <ProtectedRoute user={user} requiredRole="manager">
              <ManagerDashboard user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />
        
        <Route 
          path="/employee" 
          element={
            <ProtectedRoute user={user} requiredRole="employee">
              <EmployeeDashboard user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/attendance-scanner" 
          element={
            <ProtectedRoute user={user} requiredRole="scanner">
              <AttendanceScanner user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />
        
        <Route 
          path="/face-detection" 
          element={
            <ProtectedRoute user={user} requiredRole="employee">
              <FaceDetection user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/attendance" 
          element={
            <ProtectedRoute user={user} requiredRole="manager">
              <AttendanceManagement user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/salary" 
          element={
            <ProtectedRoute user={user} requiredRole="admin">
              <SalaryTracker user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/records" 
          element={
            <ProtectedRoute user={user} requiredRole="manager">
              <EmployeeRecords user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/users" 
          element={
            <ProtectedRoute user={user} requiredRole="manager">
              <UserManagement user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />

        <Route 
          path="/profile" 
          element={
            <ProtectedRoute user={user}>
              <ProfileSetting user={user} onLogout={handleLogout} />
            </ProtectedRoute>
          } 
        />
        
        <Route path="/" element={<Navigate to={user ? (user.userRole === 'admin' ? '/admin' : user.userRole === 'manager' ? '/manager' : '/attendance-scanner') : '/login'} />} />
      </Routes>
    </Router>
  );
}

export default App;
